begin;
set local statement_timeout='20s';
select pg_advisory_xact_lock(1617125,13);
create temporary table batch_input as select * from jsonb_to_recordset($data$[{"shop": "CellaHo", "handle": "mydecorshop", "listing_id": "4512454460", "source_url": "https://www.etsy.com/listing/4512454460/fringe-leaf-embroidered-fabric-solid", "category": "Home Decor Fabric", "board_id": "499618221101238533", "new_title": "White Raised-Embroidery Fabric for Home Projects", "body": "Raised white embroidery adds texture to this CellaHo cotton fabric. The seller lists cushion and table-cover projects among its uses. This is fabric for sewing, not a finished home accessory; choose your required cut length in the listing.", "image_url": "https://i.etsystatic.com/39663062/r/il/4d9f32/8069437622/il_794xN.8069437622_8lxd.jpg", "facebook_draft": "Planning a cushion or table-cover sewing project? Explore CellaHo\u2019s white embroidered fabric and available cut lengths. Fabric only; finished accessories are not included. https://www.etsy.com/listing/4512454460/fringe-leaf-embroidered-fabric-solid", "checked_at": "2026-10-19T02:19:08.062967+00:00", "visual_verified": true, "available": true}, {"shop": "CellaHo", "handle": "mydecorshop", "listing_id": "4486870527", "source_url": "https://www.etsy.com/listing/4486870527/vintage-chinese-floral-cotton-jacquard", "category": "Home Decor Fabric", "board_id": "499618221101238533", "new_title": "Blue Botanical Fabric for Home Sewing", "body": "Blue garden and botanical motifs decorate this CellaHo fabric. The seller suggests cushion covers, table runners and other home sewing projects. Fabric only; check the selected length option in the original listing.", "image_url": "https://i.etsystatic.com/39663062/r/il/4109d0/7900682320/il_794xN.7900682320_pm5v.jpg", "facebook_draft": "A blue-and-cream botanical fabric idea for your next home sewing project. CellaHo lists cushion and table-linen uses. This is fabric, not a finished cushion or tablecloth; choose the needed cut length. https://www.etsy.com/listing/4486870527/vintage-chinese-floral-cotton-jacquard", "checked_at": "2026-10-19T02:19:08.063162+00:00", "visual_verified": true, "available": true}]$data$::jsonb) x(shop text,listing_id text,source_url text,category text,board_id text,new_title text,body text,image_url text,checked_at timestamptz,facebook_draft text,handle text);
do $$ begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard required'; end if;
 if exists(select 1 from batch_input where checked_at<now()-interval '24 hours' or checked_at>now()) then raise exception 'Verification expired'; end if;
 if (select count(*) from batch_input x join shops s on s.shop_name=x.shop and s.status='active' join shop_social_accounts m on m.shop_id=s.id and m.active and m.platform='pinterest' join social_accounts a on a.id=m.social_account_id and a.handle=x.handle and a.active and a.platform='pinterest' join pinterest_oauth_credentials cr on cr.social_account_id=a.id and lower(cr.pinterest_username)=x.handle)<>2 then raise exception 'Batch routing or authorization changed'; end if;
end $$;
-- Report prior records before inserting; only genuinely new products enter this batch.
select json_build_object('preexisting_listing',p.etsy_listing_id,'history_count',(select count(*) from publish_history h where h.product_id=p.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id;
create temporary table new_products(id uuid,shop_id uuid,etsy_listing_id text);
with ins as (
 insert into products(shop_id,etsy_listing_id,etsy_url,title,category,listing_status,primary_image_url,original_image_urls,source_payload,source_discovered_at,last_seen_at)
 select s.id,x.listing_id,x.source_url,x.new_title,x.category,'active',x.image_url,jsonb_build_array(x.image_url),jsonb_build_object('verified_at',x.checked_at,'source',x.source_url,'image_verified',true,'batch','daily-20261019-b10'),x.checked_at,x.checked_at from batch_input x join shops s on s.shop_name=x.shop
 where not exists(select 1 from products p where p.etsy_listing_id=x.listing_id)
 on conflict(shop_id,etsy_listing_id) do nothing returning id,shop_id,etsy_listing_id
) insert into new_products select * from ins;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'pinterest','verified-original-20261019',x.image_url,x.new_title,x.body,x.source_url,x.category,'product','ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'facebook','verified-original-20261019',x.image_url,x.new_title,x.facebook_draft,x.source_url,x.category,'product','draft' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into publish_queue(shop_id,product_id,content_variant_id,platform,social_account_id,status)
select p.shop_id,p.id,cv.id,'pinterest',a.id,'ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join content_variants cv on cv.product_id=p.id and cv.platform='pinterest' join social_accounts a on a.handle=x.handle and a.platform='pinterest';
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select q.id,x.board_id,pinterest_publish_snapshot(q.id),x.checked_at,x.source_url from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest';
select json_build_object('listing_id',p.etsy_listing_id,'queue_id',q.id,'status',q.status,'board_id',r.board_id,'snapshot_matches',r.snapshot=pinterest_publish_snapshot(q.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest' join pinterest_publish_reviews r on r.queue_id=q.id;
commit;
